SOURCE = "billing"


def build_billing_event(
    resource_id: str,
    metadata: dict[str, str] | None = None,
) -> dict[str, object]:
    """Build an audit event for the billing service.

    The returned event always contains the ``event``, ``resource_id``,
    ``source`` and ``metadata`` keys.  ``metadata`` is copied so that the
    caller's mapping cannot be mutated through the returned event.
    """

    if not isinstance(resource_id, str) or not resource_id.strip():
        raise ValueError("resource_id must be a non-empty string")

    return {
        "event": "billing.charged",
        "resource_id": resource_id,
        "source": SOURCE,
        "metadata": dict(metadata) if metadata is not None else {},
    }
