def parse_port(value: str) -> int:
    """Convert a port string to an integer within the valid port range."""

    try:
        port = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Invalid port: {value!r}") from exc

    if not MIN_PORT <= port <= MAX_PORT:
        raise ValueError(
            f"Invalid port: {value!r} (must be between {MIN_PORT} and {MAX_PORT})"
        )

    return port
