import time
from collections.abc import Callable


class TtlCache[K, V]:
    """Small in-memory cache whose entries expire after a per-entry TTL."""

    def __init__(
        self,
        *,
        clock: Callable[[], float] = time.monotonic,
    ) -> None:
        self._clock = clock
        self._entries: dict[K, tuple[V, float]] = {}

    def set(
        self,
        key: K,
        value: V,
        *,
        ttl_seconds: float,
    ) -> None:
        if ttl_seconds <= 0:
            raise ValueError(
                "ttl_seconds must be greater than zero, "
                f"got {ttl_seconds!r}"
            )
        deadline = self._clock() + ttl_seconds
        self._entries[key] = (value, deadline)

    def get(self, key: K) -> V | None:
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, deadline = entry
        if self._is_expired(deadline):
            del self._entries[key]
            return None
        return value

    def delete(self, key: K) -> bool:
        return self._entries.pop(key, None) is not None

    def clear(self) -> None:
        self._entries.clear()

    @property
    def size(self) -> int:
        self._purge_expired()
        return len(self._entries)

    def _is_expired(self, deadline: float) -> bool:
        return self._clock() >= deadline

    def _purge_expired(self) -> None:
        now = self._clock()
        expired = [
            key
            for key, (_value, deadline) in self._entries.items()
            if now >= deadline
        ]
        for key in expired:
            del self._entries[key]
