import time
from collections.abc import Callable


class TtlCache[K, V]:
    """Small in-memory cache with per-entry expiration deadlines."""

    def __init__(
        self,
        clock: Callable[[], float] = time.monotonic,
    ) -> None:
        """Create an empty cache.

        ``clock`` is the single source of "current time" for the cache; it
        defaults to :func:`time.monotonic` and may be replaced with any
        callable returning a float (e.g. a fake clock in tests).
        """
        self._clock = clock
        self._entries: dict[K, V] = {}
        # Expiration deadline of every stored entry, keyed by the same key.
        # The deadline is always derived from ``self._clock``.
        self._deadlines: dict[K, float] = {}

    def set(
        self,
        key: K,
        value: V,
        *,
        ttl_seconds: float,
    ) -> None:
        self._entries[key] = value
        self._deadlines[key] = self._clock() + ttl_seconds

    def get(self, key: K) -> V | None:
        return self._entries.get(key)

    def delete(self, key: K) -> bool:
        existed = self._entries.pop(key, None) is not None
        self._deadlines.pop(key, None)
        return existed

    def clear(self) -> None:
        self._entries.clear()
        self._deadlines.clear()

    @property
    def size(self) -> int:
        return len(self._entries)
